import { useEffect, useRef, useState } from 'react'

/**
 * Replays real pipeline output for talking.MOV (generated by running lipread/ on it):
 * the 96×96 mouth crops the model saw, the jawOpen signal that segments phrases,
 * and the partial / final decodes.
 */
type ReplayData = {
  fps: number
  frames: number
  cols: number
  size: number
  jaw: number[]
  clipStart: number
  phraseStart: number
  phraseEnd: number
  partials: { frame: number; text: string }[]
  final: string
}

const HOLD_MS = 2200 // how long the final line stays up before the loop restarts
const START = 0.1
const STILL = 0.04
const JAW_MAX = 0.6

export function Replay() {
  const [data, setData] = useState<ReplayData | null>(null)
  const [frame, setFrame] = useState(0)
  const [done, setDone] = useState(false)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const spriteRef = useRef<HTMLImageElement | null>(null)

  useEffect(() => {
    fetch('/landing/replay.json')
      .then((r) => r.json())
      .then(setData)
      .catch(() => {})
    const img = new Image()
    img.src = '/landing/mouth-sprite.png'
    spriteRef.current = img
  }, [])

  useEffect(() => {
    if (!data) return
    const still = matchMedia('(prefers-reduced-motion: reduce)').matches
    if (still) {
      setFrame(data.frames - 1)
      setDone(true)
      return
    }
    const loopMs = (data.frames / data.fps) * 1000 + HOLD_MS
    const t0 = performance.now()
    let raf = 0
    const tick = (now: number) => {
      const t = (now - t0) % loopMs
      const f = Math.floor((t / 1000) * data.fps)
      setFrame(Math.min(f, data.frames - 1))
      setDone(f >= data.frames)
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [data])

  // draw the current mouth crop, nearest-neighbour so the 96 px input stays visible
  useEffect(() => {
    const c = canvasRef.current
    const img = spriteRef.current
    if (!c || !img || !data) return
    const draw = () => {
      const ctx = c.getContext('2d')!
      ctx.imageSmoothingEnabled = false
      const s = data.size
      ctx.drawImage(img, (frame % data.cols) * s, Math.floor(frame / data.cols) * s, s, s, 0, 0, c.width, c.height)
    }
    if (img.complete) draw()
    else img.onload = draw
  }, [frame, data])

  if (!data) return <div className="rp rp-loading" aria-hidden />

  const { frames, jaw, fps } = data
  const reading = frame >= data.phraseStart
  const partial = [...data.partials].reverse().find((p) => p.frame <= frame && p.text)
  const text = done ? data.final : reading ? (partial?.text ?? '') : ''
  const state = done ? 'Final' : reading ? 'Reading lips' : 'Listening'

  // jaw graph
  const W = 600
  const H = 120
  const x = (i: number) => (i / (frames - 1)) * W
  const y = (v: number) => H - (Math.min(v, JAW_MAX) / JAW_MAX) * H
  const points = jaw.map((v, i) => `${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ')

  return (
    <figure className="rp" aria-label={`Replay of the pipeline reading "${data.final}"`}>
      <header className="rp-bar">
        <span>
          <span className="rp-hide-sm">Replay / </span>talking.mov
        </span>
        <span className="rp-clock">
          Frame {String(frame + 1).padStart(3, '0')}/{String(frames).padStart(3, '0')} · {(frame / fps).toFixed(2)}s
        </span>
      </header>

      <div className="rp-main">
        <div className="rp-mouth">
          <canvas ref={canvasRef} width={384} height={384} />
          <span className="rp-tag">Model input · 96×96 · 25 fps</span>
        </div>

        <div className="rp-signal">
          <div className="rp-signal-head">
            <span>jawOpen</span>
            <span className="rp-value">{jaw[frame].toFixed(2)}</span>
          </div>
          <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" className="rp-graph">
            <rect
              x={x(data.clipStart)}
              y={0}
              width={x(frames - 1) - x(data.clipStart)}
              height={H}
              className="rp-clip"
            />
            <line x1={0} x2={W} y1={y(START)} y2={y(START)} className="rp-th rp-th-start" />
            <line x1={0} x2={W} y1={y(STILL)} y2={y(STILL)} className="rp-th" />
            <polyline points={points} className="rp-line" />
            <line x1={x(frame)} x2={x(frame)} y1={0} y2={H} className="rp-head" />
          </svg>
          <div className="rp-legend">
            <span>
              <i className="rp-key rp-key-start" /> 0.10 start
            </span>
            <span>
              <i className="rp-key" /> 0.04 pause
            </span>
            <span>
              <i className="rp-key rp-key-clip" /> clip sent to model
            </span>
          </div>
        </div>
      </div>

      <figcaption className="rp-out">
        <span className={`rp-state ${done ? 'is-final' : reading ? 'is-live' : ''}`}>{state}</span>
        <span className="rp-text">
          {text}
          {!done && <span className="rp-caret" />}
        </span>
      </figcaption>
    </figure>
  )
}
